'use client';

import * as React from 'react';
import './chip.css';

/* CHIP: a small pill with an optional leading LED or glyph and trailing actions.
 *   suggestion     frosted with a green hairline (a question with its confidence and ✓ ×)
 *   glass          a dark tag on a glass screen (an LED and a kind)
 *   glass-action   a light cap on glass (OPEN ↗), brighter on hover
 *   tag            an engraved tag in a hairline pill (a derived #tag)
 * Slots: Chip.Root, Chip.Lead, Chip.Text, Chip.Actions. */

export interface ChipRootProps extends React.HTMLAttributes<HTMLElement> {
  variant?: 'suggestion' | 'glass' | 'glass-action' | 'tag';
  as?: 'span' | 'div' | 'a' | 'button';
  href?: string;
  target?: string;
  rel?: string;
}

const Root = React.forwardRef<HTMLElement, ChipRootProps>(function ChipRoot({ variant = 'suggestion', as = 'span', className, ...props }, ref) {
  const Tag = as as React.ElementType;
  return <Tag ref={ref} data-variant={variant} className={className ? `mu-chip ${className}` : 'mu-chip'} {...props} />;
});

/** The leading LED (`led="link" | "code"`) or a glyph (children). */
function Lead({ led, children, className, ...props }: React.HTMLAttributes<HTMLSpanElement> & { led?: 'link' | 'code' }) {
  return (
    <span aria-hidden data-led={led} className={className ? `mu-chip-lead ${className}` : 'mu-chip-lead'} {...props}>
      {children}
    </span>
  );
}
function Text({ className, ...props }: React.HTMLAttributes<HTMLSpanElement>) {
  return <span className={className ? `mu-chip-text ${className}` : 'mu-chip-text'} {...props} />;
}
function Actions({ className, ...props }: React.HTMLAttributes<HTMLSpanElement>) {
  return <span className={className ? `mu-chip-actions ${className}` : 'mu-chip-actions'} {...props} />;
}

export const Chip = Object.assign(Root, { Root, Lead, Text, Actions });
export type ChipProps = ChipRootProps;

@import "../tokens.css";

/* Chip: a small pill. Its look is the chip recipe (--mu-r-chip-*). */
.mu-chip { box-sizing: border-box; display: inline-flex; align-items: center; white-space: nowrap; text-decoration: none; }
.mu-chip[data-variant="suggestion"] {
  gap: var(--mu-r-chip-suggestion-gap);
  height: var(--mu-r-chip-suggestion-height);
  padding: var(--mu-zero) var(--mu-r-chip-suggestion-pad-right) var(--mu-zero) var(--mu-r-chip-suggestion-pad-left);
  border-radius: var(--mu-radius-pill);
  font: var(--mu-r-chip-suggestion-font);
  letter-spacing: var(--mu-r-chip-suggestion-tracking);
  color: var(--mu-r-chip-suggestion-ink);
  background: var(--mu-r-chip-suggestion-background);
  box-shadow: var(--mu-r-chip-suggestion-shadow);
}
.mu-chip:is([data-variant="glass"], [data-variant="glass-action"]) {
  gap: var(--mu-r-chip-glass-gap);
  height: var(--mu-r-chip-glass-height);
  padding: var(--mu-zero) var(--mu-r-chip-glass-pad-x);
  border-radius: var(--mu-r-chip-glass-radius);
  font: var(--mu-r-chip-glass-font);
  letter-spacing: var(--mu-r-chip-glass-tracking);
}
.mu-chip[data-variant="glass"] {
  color: var(--mu-r-chip-glass-ink);
  background: var(--mu-r-chip-glass-background);
  -webkit-backdrop-filter: var(--mu-r-chip-glass-blur);
  backdrop-filter: var(--mu-r-chip-glass-blur);
}
.mu-chip[data-variant="glass-action"] { color: var(--mu-r-chip-glass-action-ink); background: var(--mu-r-chip-glass-action-background); cursor: pointer; }
.mu-chip[data-variant="glass-action"]:hover { background: var(--mu-r-chip-glass-action-hover-background); }
.mu-chip[data-variant="tag"] {
  padding: var(--mu-zero) var(--mu-r-chip-tag-pad-x);
  border-radius: var(--mu-radius-pill);
  font: var(--mu-r-chip-tag-font);
  letter-spacing: var(--mu-r-chip-tag-tracking);
  color: var(--mu-r-chip-tag-ink);
  box-shadow: var(--mu-r-chip-tag-shadow);
}
.mu-chip-lead { display: inline-grid; place-items: center; flex: none; }
.mu-chip-lead[data-led] { width: var(--mu-r-chip-led-size); height: var(--mu-r-chip-led-size); border-radius: var(--mu-round); }
.mu-chip-lead[data-led="link"] { background: var(--mu-r-chip-led-link-background); }
.mu-chip-lead[data-led="code"] { background: var(--mu-r-chip-led-code-background); }
.mu-chip-actions { display: inline-flex; align-items: center; }
.mu-chip[data-variant="suggestion"] .mu-chip-actions { gap: var(--mu-r-chip-suggestion-gap); }
